"""Self-contained administrative shell for managing monitored sites."""

# The embedded document is intentionally kept in one deployable Python module.
# Ruff's line-length rule is not useful for minified CSS and JavaScript.
# ruff: noqa: E501

ADMIN_HTML = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Web Assurance · Site configuration</title>
<style>
:root{color-scheme:dark;--bg:#08090a;--panel:#101113;--panel2:#15171a;--line:#292c31;--text:#f7f8f8;--muted:#969ba3;--green:#5ee39a;--red:#ff6b72;--blue:#8ca8ff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 20% 0,#18201c 0,transparent 30%),var(--bg);color:var(--text);font:14px/1.5 Inter,system-ui,-apple-system,sans-serif}button,input,textarea{font:inherit}.shell{max-width:1180px;margin:auto;padding:28px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.brand{font-weight:600;letter-spacing:-.02em}.brand span{color:var(--green)}.status{color:var(--muted);font-size:12px}.grid{display:grid;grid-template-columns:280px 1fr;gap:18px}.panel{background:rgba(16,17,19,.92);border:1px solid var(--line);border-radius:14px;box-shadow:0 20px 70px #0005}.sidebar{padding:14px;min-height:650px}.main{padding:22px}.eyebrow{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.12em;margin-bottom:8px}h1{font-size:25px;margin:0 0 6px;letter-spacing:-.03em}p{color:var(--muted);margin:0 0 20px}.auth{display:flex;gap:8px;margin-bottom:18px}.auth input{flex:1}.site{display:flex;align-items:center;justify-content:space-between;width:100%;padding:11px;border:0;border-radius:9px;background:transparent;color:var(--text);text-align:left;cursor:pointer}.site:hover,.site.active{background:var(--panel2)}.dot{width:7px;height:7px;border-radius:50%;background:var(--green);display:inline-block;margin-right:8px}.add{width:100%;margin-top:10px}.row{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field{margin:14px 0}.field label{display:block;color:#c8cbd0;font-size:12px;margin-bottom:6px}.field small{display:block;color:var(--muted);margin-top:5px}input,textarea{width:100%;color:var(--text);background:#0b0c0e;border:1px solid var(--line);border-radius:8px;padding:10px 11px;outline:none}input:focus,textarea:focus{border-color:#526e60;box-shadow:0 0 0 3px #5ee39a12}textarea{min-height:82px;resize:vertical}button{border:1px solid var(--line);background:#191b1f;color:var(--text);border-radius:8px;padding:9px 12px;cursor:pointer}button.primary{background:var(--green);border-color:var(--green);color:#07110b;font-weight:600}button.danger{color:var(--red)}.actions{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line);padding-top:18px;margin-top:22px}.notice{min-height:21px;color:var(--muted)}.notice.ok{color:var(--green)}.notice.bad{color:var(--red)}.empty{padding:70px 20px;text-align:center;color:var(--muted)}.operations{border-top:1px solid var(--line);margin-top:26px;padding-top:22px}.operations h2,.modal h2{margin:0 0 6px;font-size:18px}.operations select{width:100%;color:var(--text);background:#0b0c0e;border:1px solid var(--line);border-radius:8px;padding:10px 11px}.modal{position:fixed;inset:0;background:#000b;display:grid;place-items:center;padding:20px;z-index:10}.modal[hidden]{display:none}.modal-card{width:min(760px,100%);max-height:80vh;overflow:auto;background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:20px;box-shadow:0 30px 100px #000}.modal-card .actions{margin-top:0}.modal pre{min-height:280px;white-space:pre-wrap;background:#090a0b;border:1px solid var(--line);border-radius:8px;padding:14px;color:#cfd4d8}@media(max-width:760px){.shell{padding:14px}.grid{grid-template-columns:1fr}.sidebar{min-height:auto}.row{grid-template-columns:1fr}.top{align-items:flex-start;gap:12px}}
</style></head>
<body><div class="shell"><div class="top"><div class="brand"><span>TECH X</span> · Web Assurance</div><div class="status">Configuration console</div></div><div class="auth"><input id="token" type="password" autocomplete="current-password" placeholder="Administrative token (X-Triage-Token)"><button id="connect" class="primary">Connect</button></div><div class="grid"><aside class="panel sidebar"><div class="eyebrow">Monitored sites</div><div id="sites"></div><button id="add" class="add">+ Add site</button></aside><main class="panel main"><div id="empty" class="empty">Connect to load the site manifest.</div><form id="form" hidden><div class="eyebrow">Site configuration</div><h1 id="heading">Site</h1><p>Define the public page and the evidence that proves it is functioning.</p><div class="row"><div class="field"><label>Site ID</label><input id="siteId" required pattern="[a-z0-9][a-z0-9_-]*"></div><div class="field"><label>Page ID</label><input id="pageId" required pattern="[a-z0-9][a-z0-9_-]*"></div></div><div class="field"><label>Page URL</label><input id="url" type="url" required placeholder="https://example.com/"><small>The hostname must already be approved in TRIAGE_ALLOWED_HOSTS.</small></div><div class="row"><div class="field"><label>Required text · one per line</label><textarea id="requiredText"></textarea></div><div class="field"><label>Required selectors · one per line</label><textarea id="selectors" placeholder="main\nheader\nfooter"></textarea></div></div><div class="row"><div class="field"><label>Forbidden error text · one per line</label><textarea id="forbidden"></textarea></div><div class="field"><label>Ignored resource paths · one per line</label><textarea id="ignored"></textarea></div></div><div class="row"><div class="field"><label>Fast check interval · seconds</label><input id="fast" type="number" min="60" max="300" placeholder="Optional"></div><div class="field"><label>Deep check interval · seconds</label><input id="deep" type="number" min="900" max="3600" placeholder="Optional"></div></div><div class="field"><label><input id="ignoreConsole" type="checkbox" style="width:auto;margin-right:8px">Treat known console errors as informational</label><small>Use only after confirming the errors do not impair the monitored workflow.</small></div><section class="operations"><div class="eyebrow">Verification</div><h2>Run assurance checks</h2><p>Test reachability or execute the configured browser assertions with live progress.</p><div class="actions"><div><button id="testLink" type="button">Test link</button> <button id="runTests" type="button" class="primary">Run tests</button></div></div></section><section class="operations"><div class="eyebrow">Reference screenshots</div><h2>Expected appearance</h2><p>Upload an approved PNG for each viewport. Future visual checks compare live captures against it.</p><div class="row"><div class="field"><label>Viewport</label><select id="baselineViewport"></select></div><div class="field"><label>Operator label</label><input id="operator" placeholder="Your name" autocomplete="name"></div></div><div class="field"><label>Reference PNG</label><input id="baselineFile" type="file" accept="image/png"></div><button id="uploadBaseline" type="button">Upload and approve</button></section><div class="actions"><button id="remove" type="button" class="danger">Remove site</button><div><span id="notice" class="notice"></span> <button class="primary" type="submit">Save manifest</button></div></div></form></main></div></div><div id="runModal" class="modal" hidden><div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="runTitle"><div class="actions"><h2 id="runTitle">Test run</h2><button id="closeModal" type="button" aria-label="Close test log">Close</button></div><pre id="runLog" aria-live="polite"></pre></div></div>
<script>
const $=id=>document.getElementById(id), lines=v=>v.split('\n').map(x=>x.trim()).filter(Boolean);let manifest=null,index=0;
function auth(){return {'Authorization':'Bearer '+$('token').value,'Content-Type':'application/json'}}
function defaultPage(){return {id:'new-page',url:'https://',viewports:[{id:'desktop',width:1440,height:900,device_scale_factor:1.0},{id:'mobile',width:390,height:844,device_scale_factor:1.0}],required_text:[],required_selectors:['main'],forbidden_text:[],ignored_resource_patterns:[],ignore_console_errors:false}}
function render(){if(!manifest)return;const box=$('sites');box.replaceChildren();manifest.sites.forEach((s,i)=>{const b=document.createElement('button'),name=document.createElement('span'),dot=document.createElement('i'),arrow=document.createElement('span');b.className='site '+(i===index?'active':'');dot.className='dot';name.append(dot,document.createTextNode(s.id));arrow.textContent='›';b.append(name,arrow);b.onclick=()=>{capture();index=i;render()};box.appendChild(b)});$('empty').hidden=true;$('form').hidden=false;fill()}
function fill(){const s=manifest.sites[index],p=s.pages[0];$('heading').textContent=s.id;$('siteId').value=s.id;$('pageId').value=p.id;$('url').value=p.url;$('requiredText').value=(p.required_text||[]).join('\n');$('selectors').value=(p.required_selectors||[]).join('\n');$('forbidden').value=(p.forbidden_text||[]).join('\n');$('ignored').value=(p.ignored_resource_patterns||[]).join('\n');$('fast').value=p.fast_check_interval_seconds||'';$('deep').value=p.deep_check_interval_seconds||'';$('ignoreConsole').checked=!!p.ignore_console_errors;const options=(p.viewports||[]).map(v=>new Option(`${v.id} · ${v.width}×${v.height}`,v.id));$('baselineViewport').replaceChildren(...options)}
function capture(){if(!manifest||!manifest.sites[index])return;const s=manifest.sites[index],p=s.pages[0],u=$('url').value; s.id=$('siteId').value;p.id=$('pageId').value;p.url=u;try{s.allowed_hosts=[new URL(u).hostname]}catch{}p.required_text=lines($('requiredText').value);p.required_selectors=lines($('selectors').value);p.forbidden_text=lines($('forbidden').value);p.ignored_resource_patterns=lines($('ignored').value);p.ignore_console_errors=$('ignoreConsole').checked;for(const [k,id] of [['fast_check_interval_seconds','fast'],['deep_check_interval_seconds','deep']]){const v=$(id).value;if(v)p[k]=Number(v);else delete p[k]}}
async function connect(){notice('Connecting…');const r=await fetch('/admin/api/manifest',{headers:auth()});if(!r.ok){notice(r.status===401?'Invalid administrative token.':'Unable to load manifest.',false);return}manifest=await r.json();index=0;render();notice('Connected.',true)}
async function save(e){e.preventDefault();capture();notice('Validating and saving…');const r=await fetch('/admin/api/manifest',{method:'PUT',headers:auth(),body:JSON.stringify(manifest)});const data=await r.json().catch(()=>({}));if(!r.ok){notice(data.detail||'Save failed.',false);return}manifest=await (await fetch('/admin/api/manifest',{headers:auth()})).json();render();notice('Saved. Restart the service to apply scheduler changes.',true)}
function currentPage(){capture();return manifest.sites[index].pages[0]}
async function testLink(){const p=currentPage();notice('Testing link…');const r=await fetch(`/admin/api/pages/${encodeURIComponent(p.id)}/test-link`,{method:'POST',headers:auth()});const d=await r.json().catch(()=>({}));notice(r.ok?`Reachable · HTTP ${d.status_code} · ${d.latency_ms} ms`:d.detail||d.error||'Link test failed.',r.ok)}
function logLine(text){$('runLog').textContent+=text+'\n';$('runLog').scrollTop=$('runLog').scrollHeight}
async function runTests(){const p=currentPage();$('runLog').textContent='';$('runModal').hidden=false;$('closeModal').focus();try{const r=await fetch(`/admin/api/pages/${encodeURIComponent(p.id)}/run-tests`,{method:'POST',headers:auth()});if(!r.ok){const d=await r.json().catch(()=>({}));logLine(d.detail||'Unable to run tests.');return}const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {done,value}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});const lines=buffer.split('\n');buffer=lines.pop()||'';for(const line of lines){if(!line)continue;const e=JSON.parse(line);if(e.event==='start')logLine(`Starting ${e.page_id}…`);else if(e.event==='viewport'){const notes=e.information_codes?.length?' · info: '+e.information_codes.join(', '):'';logLine(`${e.status==='passed'?'PASS':'FAIL'} ${e.viewport_id} · ${e.duration_ms} ms${e.failure_codes.length?' · '+e.failure_codes.join(', '):''}${notes}`);for(const error of e.console_errors||[])logLine(`  console · ${error}`)}else logLine(`Complete · ${e.classification}`)}if(done)break}}catch(error){logLine(`Test run interrupted · ${error.message}`)}}
async function uploadBaseline(){const p=currentPage(),file=$('baselineFile').files[0],viewport=$('baselineViewport').value,operator=$('operator').value.trim();if(!file||!operator){notice('Choose a PNG and enter the operator name.',false);return}notice('Uploading reference…');const headers=auth();delete headers['Content-Type'];headers['X-Operator-Label']=operator;const r=await fetch(`/admin/api/pages/${encodeURIComponent(p.id)}/baselines/${encodeURIComponent(viewport)}`,{method:'PUT',headers,body:file});const d=await r.json().catch(()=>({}));notice(r.ok?'Reference screenshot approved.':d.detail||'Upload failed.',r.ok)}
function notice(t,ok){$('notice').textContent=t;$('notice').className='notice '+(ok===true?'ok':ok===false?'bad':'')}
$('connect').onclick=connect;$('form').onsubmit=save;$('testLink').onclick=testLink;$('runTests').onclick=runTests;$('uploadBaseline').onclick=uploadBaseline;$('closeModal').onclick=()=>{$('runModal').hidden=true;$('runTests').focus()};$('add').onclick=()=>{if(!manifest)return;capture();const n=manifest.sites.length+1;manifest.sites.push({id:'new-site-'+n,allowed_hosts:['example.com'],pages:[defaultPage()]});index=manifest.sites.length-1;render()};$('remove').onclick=()=>{if(!manifest||manifest.sites.length<=1){notice('At least one site is required.',false);return}manifest.sites.splice(index,1);index=Math.max(0,index-1);render()};$('token').addEventListener('keydown',e=>{if(e.key==='Enter')connect()});
</script></body></html>"""
